class Policy:
    # Changed: use UCB-style exploration to balance known-good tasks vs untested ones,
    # and avoid wasting picks on solved tasks by tracking attempts per task.
    def __init__(self):
        self.scores = {}
        self.attempts = {}
        self.total_attempts = 0

    def pick(self, keys, round_index):
        # Filter to unsolved tasks (score < 1.0 or unknown)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            return keys[round_index % len(keys)]

        # UCB1: prefer tasks with high average score but also explore untested ones
        import math
        best_key = None
        best_ucb = -float('inf')
        for k in unsolved:
            n = self.attempts.get(k, 0)
            if n == 0:
                # Untested: high exploration bonus
                ucb = float('inf')
            else:
                avg = self.scores.get(k, 0) / n
                # Exploration term: sqrt(2*ln(total)/n)
                ucb = avg + math.sqrt(2 * math.log(self.total_attempts + 1) / n)
            if ucb > best_ucb:
                best_ucb = ucb
                best_key = k
        return best_key

    def record(self, task_id, score):
        self.scores[task_id] = self.scores.get(task_id, 0) + score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
        self.total_attempts += 1
